    That seems to have been lost during refactoring in bug 2001258.

    Differential Revision: https://phabricator.services.mozilla.com/D283370

diff --git a/mail/base/content/widgets/tree-view.mjs b/mail/base/content/widgets/tree-view.mjs
index 7c0257a962f..91f6cf82b63 100644
--- a/mail/base/content/widgets/tree-view.mjs
+++ b/mail/base/content/widgets/tree-view.mjs
@@ -2544,6 +2544,7 @@ class TreeViewTableHeaderCell extends HTMLTableCellElement {
     this.#button = document.createElement("button");
     this.#container.appendChild(this.#button);
     const pickerButton = document.createElement("button");
+    document.l10n?.setAttributes(pickerButton, "tree-list-view-column-picker");
     pickerButton.classList.add("button-flat", "button-column-picker");
     pickerButton.tabIndex = -1;
     pickerButton.appendChild(document.createElement("img"));
